sys_script.script:
(function executeRule(current, previous) {
    var calc = new x_2298436_snackf_0.SnackFlowCalc()

    var invoiceId = current.getValue('invoice')
    if (invoiceId) {
        // Full re-sum of every payment row for the invoice - never an increment.
        calc.recalcInvoicePayments(invoiceId)
    }

    // If the payment was re-parented to a different invoice, the invoice it
    // used to belong to must be recomputed as well.
    if (previous) {
        var previousInvoiceId = previous.getValue('invoice')
        if (previousInvoiceId && previousInvoiceId !== invoiceId) {
            calc.recalcInvoicePayments(previousInvoiceId)
        }
    }
})(current, previous)
